from pathlib import Path
import json,subprocess,base64,hashlib,shutil,os
ROWS=[{'file': 'tools/stage5_02_board_run.py', 'before': '6bb9f516e13abcf8c1ca9984b7671abe19c91182e9241f9d14a56ac6c38a8f8a', 'sha256': '01da83e6b4eaca3b6ce3b0204ce7cbcb6ca354cff0de0077bc324e323410adc0', 'data': ''}, {'file': 'tests/stage5_02_replay_pair.tsv', 'before': None, 'sha256': '7079fcead7fc22ef0d5ee034be25974caa047ceb25187265e739f1901126f54c', 'data': 'MAnliY3pnaLmnInku4DkuYgNCjEwMDAJ5LiA5Yqg5LiA562J5LqO5YegDQo='}]

root=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review');assert root.is_dir() and not root.is_symlink()
report=root/'reports/stage5_02_board/equal_work_setup';report.mkdir()
for row in ROWS:
 p=root/row['file'];assert p.resolve().is_relative_to(root) and not p.is_symlink()
 if row['before'] is None:assert not p.exists()
 else:assert hashlib.sha256(p.read_bytes()).hexdigest()==row['before']
for row in ROWS:
 p=root/row['file'];data=base64.b64decode(row['data']);assert hashlib.sha256(data).hexdigest()==row['sha256']
 if p.exists():shutil.copyfile(p,report/p.name)
 p.write_bytes(data)
(report/'manifest.json').write_text(json.dumps([{k:v for k,v in r.items() if k!='data'} for r in ROWS],indent=2))
for variant in ['baseline','candidate']:
 command=['python3',str(root/'tools/stage5_02_board_run.py'),'--name',variant+'_equal_work_pair','--variant',variant,'--replay','--replay-source','pair','--tts-queue-ms','60000','--request-lifetime-ms','120000','--seconds','30','--timeout','180','--grace','60']
 print('COMMAND',json.dumps(command),flush=True)
 code=subprocess.run(command,timeout=260).returncode
 if code:raise SystemExit(code)
